import functools
from typing import ForwardRef, Any, Callable
import inspect
from fastapi.dependencies.utils import get_typed_signature

# Define a type that will be used as a forward reference
class MyType:
    pass

def original_func(a: "MyType") -> None:
    pass

@functools.wraps(original_func)
def wrapped_func(a: "MyType") -> None:
    pass

def test_wrapped_signature():
    try:
        sig = get_typed_signature(wrapped_func)
        print("Signature obtained successfully")
        # Check if the annotation was resolved to MyType
        param = sig.parameters['a']
        print(f"Annotation: {param.annotation}")
        assert param.annotation is MyType
    except Exception as e:
        print(f"Error: {e}")
        raise e

if __name__ == "__main__":
    test_wrapped_signature()

