from typing import ForwardRef, Any, Callable, Dict
from fastapi.dependencies.utils import get_typed_signature

# Define User in a separate "module" context by putting it in a function
# but we want it to be in the globals of the original function.
# The issue is that if the wrapper is defined in a different module or 
# the globals are different, it fails.

def create_module_context():
    class User:
        pass

    def original_func(user: "User"):
        return user

    @functools.wraps(original_func)
    def wrapper_func(user: "User"):
        return original_func(user)

    return wrapper_func

def test_repro():
    wrapper = create_module_context()
    try:
        sig = get_typed_signature(wrapper)
        print("Successfully got signature")
        param = sig.parameters['user']
        print(f"Annotation: {param.annotation}")
    except NameError as e:
        print(f"Caught NameError: {e}")
        raise e
    except Exception as e:
        print(f"Caught exception: {type(e).__name__}: {e}")
        raise e

if __name__ == "__main__":
    test_repro()
